for(const b of document.querySelectorAll('.close-dialog'))b.onclick=()=>b.closest('dialog').close();$('replaceDialog').addEventListener('close',()=>pendingAudio=null);$('videoDialog').addEventListener('close',()=>$('videoPreview').pause());
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('stageWrap').requestFullscreen();}catch{toast('Full-screen preview is unavailable here.');}};
document.addEventListener('keydown',e=>{
 if(busy||e.target.closest('input,textarea,select,[contenteditable=true]')||document.querySelector('dialog[open]'))return;
 const modified=e.ctrlKey||e.metaKey||e.altKey;
 if((e.code==='Space'||e.key===' ')&&!modified){e.preventDefault();if(!e.repeat)mark(spaceAction);return;}
 if(e.repeat)return;
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo();return;}
 if(e.key==='Escape'){if(drag)cancelDrag();else pause();return;}
 if(e.key.toLowerCase()==='t'&&!modified){e.preventDefault();tapTempo();return;}
 if(e.key.toLowerCase()==='p'&&!modified){e.preventDefault();void play();return;}
 if(/^[1-9]$/.test(e.key)&&!modified){e.preventDefault();mark(ORDER[Number(e.key)-1]);}
 if(e.key==='Delete'&&selected){e.preventDefault();$('deleteCue').click();}
});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&player.playing){const capturing=armed;pause();if(capturing)toast('Cue recording paused. Your take is saved.');}});window.addEventListener('beforeunload',e=>{if(exportJob||armed){e.preventDefault();e.returnValue='';}});new ResizeObserver(()=>{renderMarkers();paint();}).observe($('waveViewport'));
window.PlayAlongStudio={getProject:()=>clone(project),getStatus:()=>({playing:player.playing,recordingCues:armed,exporting:!!exportJob,busy,seconds,audioReady:ready(),cues:activeEvents(project).length,duration:showTiming(project).total}),loadProject:raw=>{if(busy)return false;pause();const next=validateProject(raw);remember(project);project=next;selected=null;seconds=0;player.position=0;if(record?.id!==project.audio?.id){record=null;player.buffer=null;peaks=null;void restoreAudio();}persist();renderAll();return true;},play,pause,seek,recordCues:capture,markCue:mark,saveProject,renderVideo:exportMovie,renderFrame:t=>{if(!player.playing&&!busy){seconds=clamp(Number(t)||0,0,showTiming(project).total);player.position=seconds;paint();}}};
renderAll();requestAnimationFrame(frame);if(project.audio)void restoreAudio();
